import os
import json
import sys

p = r"C:\Users\yanxiaoan\.gemini\antigravity\brain\198bf830-742d-4422-8d4a-264fa65f2821\.system_generated\logs\transcript.jsonl"
if os.path.exists(p):
    with open(p, "r", encoding="utf-8") as f:
        for line in f:
            d = json.loads(line)
            print(f"Step {d.get('step_index')}: {d.get('type')} ({d.get('source')})")
            if d.get('content'):
                print("  Content snippet:", d.get('content')[:150].replace('\n', ' '))
            if d.get('tool_calls'):
                for tc in d.get('tool_calls'):
                    print("  Tool call:", tc.get('name'))
